    // Master latch: transparent when clk=1
    // Slave latch: transparent when clk=0
    // Reset clears both latches
    // Output q is slave output

endmodule

testbench:
`timescale 1ns/1ps
module tb();
    reg clk, rst, d;
    wire q;
    integer passed = 0;

    master_slave_dff dut (.clk(clk), .rst(rst), .d(d), .q(q));

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        $display("Testing Master-Slave D Flip-Flop...");

        // Test async reset
        rst=0; d=1; #10;
        if(q !== 0) $display("FAIL: Reset should clear Q=0"); 
        else passed++;

        // Release reset
        rst=1; #10;

        // Setup D before posedge
        d=1; @(negedge clk); #1;
        // Now clock is low, master should be transparent
        // But output shouldn't change until next posedge

        // At posedge, master captures, slave still holds old
        @(posedge clk); #1;
        // Q might not change yet because slave transparent on negedge

        // Wait for negedge when slave becomes transparent
        @(negedge clk); #1;
        if(q !== 1) $display("FAIL: Should output D=1 after full cycle"); 
        else passed++;

        // Change D during clock high
        d=0; #5; // During clock high
        if(q !== 1) $display("FAIL: Should hold during clock high"); 
        else passed++;

        // At next negedge, slave gets master's value (which is 0 now)
        @(negedge clk); #1;
        if(q !== 0) $display("FAIL: Should update to D=0"); 
        else passed++;

        // Test reset during operation
        d=1; rst=0; #1;
        if(q !== 0) $display("FAIL: Async reset should work immediately"); 
        else passed++;

        // Test that changes only happen after full clock cycle
        rst=1; d=1; @(posedge clk); #1;
        // Q should still be 0 because slave not transparent yet
        if(q !== 0) $display("FAIL: Should not change immediately at posedge"); 
        else passed++;

        @(negedge clk); #1;
        if(q !== 1) $display("FAIL: Should change at negedge"); 
        else passed++;

        if(passed==7) $display("PASS: Master-slave DFF works correctly"); 
        else $display("FAIL: Some test cases failed");
        #20 $finish;
    end
